import { randomBytes } from "crypto"
import type { AccountStatus } from "./accounts/types"
import { assessAgent, type AgentAssessment } from "./agents/assessment"
import type { AgentMetadata } from "./agents/discovery"
import type { AiResult } from "./ai"
import type { PriceChange } from "./domain/changes"
import { isFreePricing, type ModelOffer } from "./domain/model"
import type { ProviderSnapshot } from "./domain/provider"
import { rankOffers, type Purpose } from "./domain/ranking"

export interface DashboardState { snapshots: ProviderSnapshot[]; history: PriceChange[]; agents: AgentMetadata[]; accounts: AccountStatus[]; ai: AiResult | null; updatedAt: number }
const esc = (value: unknown) => String(value ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")
const price = (value: number, unknown?: boolean) => unknown ? "–" : new Intl.NumberFormat("de-DE", { maximumFractionDigits: 4 }).format(value)
const labels: Record<Purpose,string> = { coding:"Coding", language:"Sprache", reasoning:"Reasoning", vision:"Vision", tools:"Tools", allround:"Allround" }
const statusLabel: Record<AgentAssessment["status"],string> = { suitable:"Passend", expensive:"Teuer", "alternative-available":"Alternative", unsuitable:"Unpassend", deprecated:"Veraltet", unknown:"Unklar" }
const ACCOUNT_CSS = `.account-main{min-width:0}.account-main>*{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-usage{color:var(--vscode-descriptionForeground);font-size:.82em}.account-item .status{max-width:220px}`

function renderAgent(assessment: AgentAssessment, compact = false): string {
  const { agent, status, reason, alternative } = assessment
  return `<article class="agent-item ${compact ? "agent-preview" : ""}"><div class="agent-main"><strong>${esc(agent.name)}</strong><span class="agent-model">${esc(agent.model || "Kein Modell zugewiesen")}</span>${compact ? "" : `<span class="subtle">${esc(reason)}</span>`}</div><span class="status status-${status}">${esc(statusLabel[status])}</span>${!compact && alternative ? `<div class="agent-alt">Empfehlung: <strong>${esc(alternative.name)}</strong></div>` : ""}</article>`
}

function renderAccount(account: AccountStatus): string {
  const value = account.remainingUsd !== undefined
    ? `${price(account.remainingUsd)} $ verfügbar`
    : account.state === "available"
      ? "Verbunden · kein festes Schlüssellimit"
      : account.message ?? "Verbrauch nicht abrufbar"
  const usage = [["Heute",account.dailyUsd],["Woche",account.weeklyUsd],["Monat",account.monthlyUsd]].filter((item): item is [string,number]=>item[1] !== undefined).map(([period,amount])=>`${period} ${price(amount)} $`).join(" · ")
  return `<article class="account-item"><div class="account-main"><strong>${esc(account.provider)}</strong>${account.label ? `<span class="subtle">${esc(account.label)}</span>` : ""}${usage ? `<span class="account-usage">${esc(usage)}</span>` : ""}</div><span class="status status-${account.state === "available" ? "suitable" : account.state}">${esc(value)}</span></article>`
}

function renderRanks(offers: ModelOffer[]): string {
  return (Object.entries(labels) as Array<[Purpose,string]>).map(([purpose,label],index) => {
    const list = (mode: "free"|"paid") => {
      const ranked = rankOffers(offers,purpose,mode).filter((item)=>item.rating === "scored").slice(0,3)
      return ranked.length ? `<ol>${ranked.map((item)=>`<li><span>${esc(item.offer.name)}</span><small>${item.score} · ${price(item.offer.pricing.input)}/${price(item.offer.pricing.output)} $</small></li>`).join("")}</ol>` : `<p class="empty">Noch keine belastbar bewerteten Modelle</p>`
    }
    return `<details${index===0 ? " open" : ""}><summary>${label}</summary><div class="rank-columns"><div><h4>Kostenlos</h4>${list("free")}</div><div><h4>Kostenpflichtig</h4>${list("paid")}</div></div></details>`
  }).join("")
}

export function panelHtml(state: DashboardState): string {
  const nonce = randomBytes(16).toString("base64")
  const offers = state.snapshots.flatMap((snapshot)=>snapshot.offers)
  const free = offers.filter((offer)=>isFreePricing(offer.pricing)).length
  const assessments = state.agents.map((agent)=>assessAgent(agent,offers))
  const previews = assessments.slice(0,4).map((item)=>renderAgent(item,true)).join("") || `<p class="empty">Keine Agenten erkannt</p>`
  const allAgents = assessments.map((item)=>renderAgent(item)).join("") || `<p class="empty">Keine Agenten erkannt</p>`
  const accounts = state.accounts.map(renderAccount).join("") || `<p class="empty">Noch kein Konto verbunden</p>`
  const rows = offers.slice().sort((a,b)=>a.name.localeCompare(b.name)).map((offer)=>`<tr data-model="${esc(`${offer.name} ${offer.provider} ${offer.capabilities.purposes.join(" ")}`.toLowerCase())}" data-provider="${offer.provider}" data-price="${isFreePricing(offer.pricing)?"free":offer.pricing.unknown?"unknown":"paid"}"><td><strong>${esc(offer.name)}</strong><small>${esc(offer.id)}</small></td><td><span class="provider provider-${offer.provider}">${esc(offer.provider.replace("opencode-",""))}</span></td><td>${price(offer.pricing.input,offer.pricing.unknown)}</td><td>${price(offer.pricing.output,offer.pricing.unknown)}</td><td><div class="tags">${offer.capabilities.purposes.map((tag)=>`<span>${esc(labels[tag])}</span>`).join("")}</div></td></tr>`).join("")
  const providerErrors = state.snapshots.filter((snapshot)=>snapshot.error).map((snapshot)=>`<div class="notice error">${esc(snapshot.provider)}: ${esc(snapshot.error?.message)}</div>`).join("")
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="content-security-policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'"><style>${CSS}${ACCOUNT_CSS}</style></head><body>
  <header class="topbar"><button class="brand" data-view="overview">Preis-Watch</button><nav><button data-view="overview" class="active">Übersicht</button><button data-view="models">Modelle</button><button data-view="agents">Agenten</button><button data-view="accounts">Konten &amp; Limits</button></nav><span class="live"><i></i> aktuell</span></header>${providerErrors}
  <main><section class="view" id="overview"><div class="metrics"><span><strong>${offers.length}</strong> Modelle</span><span><strong>${free}</strong> kostenlos</span><span><strong>${state.history.length}</strong> Änderungen</span><span><strong>${state.agents.length}</strong> Agenten</span></div><div class="insight"><strong>✦ KI-Fazit</strong><span>${esc(state.ai?.text ?? "Preis- und Agentendaten werden lokal ausgewertet.")}</span></div><div class="dashboard"><section class="card rankings"><h2>Beste Modelle für deinen Zweck</h2>${renderRanks(offers)}</section><section class="card agents-card"><div class="card-head"><h2>Deine Agenten</h2><button data-view="agents">Alle ${assessments.length}</button></div>${previews}${assessments.length>4?`<button class="more" data-view="agents">Mehr Agenten anzeigen</button>`:""}</section><section class="card accounts-card"><div class="card-head"><h2>Konten &amp; Limits</h2><button data-view="accounts">Details</button></div>${accounts}</section></div></section>
  <section class="view" id="models" hidden><div class="page-head"><div><h1>Alle Modelle</h1><p>${offers.length} Angebote von OpenRouter, Zen und Go</p></div></div><div class="filters"><input id="search" placeholder="Modelle durchsuchen"><select id="provider"><option value="">Alle Anbieter</option><option value="openrouter">OpenRouter</option><option value="opencode-zen">OpenCode Zen</option><option value="opencode-go">OpenCode Go</option></select><select id="price"><option value="">Alle Preise</option><option value="free">Kostenlos</option><option value="paid">Kostenpflichtig</option><option value="unknown">Preis auf Anfrage</option></select><select id="purpose"><option value="">Alle Fähigkeiten</option>${Object.entries(labels).map(([value,label])=>`<option value="${value}">${label}</option>`).join("")}</select></div><div class="table-wrap"><table><thead><tr><th>Modell</th><th>Anbieter</th><th>Input / 1M</th><th>Output / 1M</th><th>Fähigkeiten</th></tr></thead><tbody>${rows}</tbody></table></div></section>
  <section class="view" id="agents" hidden><div class="page-head"><div><h1>Deine Agenten</h1><p>Aktuelle Modellzuordnung und nachvollziehbare Empfehlungen</p></div></div><div class="agent-list">${allAgents}</div></section>
  <section class="view" id="accounts" hidden><div class="page-head"><div><h1>Konten &amp; Limits</h1><p>Verbindungen werden ausschließlich im lokalen VS Code Secret Store gespeichert.</p></div><div><button class="primary" data-action="connect">Konto verbinden</button><button data-action="disconnect">Verbindung entfernen</button></div></div><div class="account-grid">${accounts}</div></section></main>
  <script nonce="${nonce}">${SCRIPT}</script></body></html>`
}

const SCRIPT = `const vscode=acquireVsCodeApi();const show=id=>{document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==id);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo(0,0)};document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>vscode.postMessage({type:b.dataset.action})));const filter=()=>{const q=search.value.toLowerCase(),p=provider.value,c=price.value,u=purpose.value;document.querySelectorAll('[data-model]').forEach(r=>r.hidden=!(r.dataset.model.includes(q)&&(!p||r.dataset.provider===p)&&(!c||r.dataset.price===c)&&(!u||r.dataset.model.includes(u))))};['search','provider','price','purpose'].forEach(id=>document.getElementById(id).addEventListener(id==='search'?'input':'change',filter));`

const CSS = `:root{color-scheme:light dark;--accent:#a78bfa;--mint:#4ade80;--warn:#fbbf24;--danger:#fb7185}*{box-sizing:border-box}body{margin:0;color:var(--vscode-foreground);background:var(--vscode-editor-background);font:var(--vscode-font-size)/1.4 var(--vscode-font-family)}button,input,select{font:inherit}.topbar{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:22px;min-height:44px;padding:0 16px;border-bottom:1px solid var(--vscode-panel-border);background:color-mix(in srgb,var(--vscode-editor-background) 94%,transparent);backdrop-filter:blur(12px)}button{border:1px solid var(--vscode-button-border,transparent);border-radius:5px;padding:5px 10px;color:var(--vscode-button-secondaryForeground);background:var(--vscode-button-secondaryBackground);cursor:pointer}.topbar button{border:0;padding:11px 0;background:none;color:var(--vscode-descriptionForeground)}.topbar .brand{font-weight:700;color:var(--vscode-foreground)}.topbar nav{display:flex;gap:20px}.topbar nav button.active{color:var(--accent);box-shadow:inset 0 -2px var(--accent)}.live{margin-left:auto;color:var(--vscode-descriptionForeground)}.live i{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--mint)}main{padding:12px 16px}.metrics{display:flex;flex-wrap:wrap;gap:10px 30px;padding:3px 2px 10px;color:var(--vscode-descriptionForeground)}.metrics strong{font-size:1.35em;color:var(--vscode-foreground)}.insight{display:flex;gap:8px;padding:7px 10px;margin-bottom:7px;border-left:3px solid var(--accent);border-radius:4px;background:color-mix(in srgb,var(--accent) 14%,var(--vscode-editorWidget-background))}.insight strong{white-space:nowrap;color:#d8b4fe}.dashboard{display:grid;grid-template-columns:minmax(360px,2fr) minmax(220px,1fr) minmax(220px,1fr);gap:7px;align-items:start}.card{min-width:0;padding:8px 10px;border:1px solid var(--vscode-panel-border);border-radius:8px;background:var(--vscode-editorWidget-background)}h1,h2,h4,p{margin:0}h1{font-size:1.5em}h2{font-size:1em;margin-bottom:5px}h4{font-size:.9em;color:var(--vscode-descriptionForeground)}details{border-top:1px solid color-mix(in srgb,var(--vscode-panel-border) 55%,transparent)}details:first-of-type{border-top:0}summary{padding:4px 0;cursor:pointer}.rank-columns{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:2px 0 6px}.rank-columns ol{margin:2px 0 0;padding-left:20px}.rank-columns li{padding:2px 0}.rank-columns li span,.rank-columns li small{display:block}.rank-columns li small,.subtle,.agent-model,.empty,.page-head p{color:var(--vscode-descriptionForeground);font-size:.88em}.card-head,.page-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.card-head button{padding:2px 6px;background:none;color:var(--accent)}.agent-item,.account-item{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px;align-items:center;padding:5px 0;border-bottom:1px solid color-mix(in srgb,var(--vscode-panel-border) 45%,transparent)}.agent-item:last-of-type,.account-item:last-of-type{border-bottom:0}.agent-main{min-width:0}.agent-main>*{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.status{max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.82em;font-weight:600}.status-suitable,.status-available{color:var(--mint)}.status-alternative-available,.status-low{color:var(--warn)}.status-deprecated,.status-unsuitable,.status-exhausted{color:var(--danger)}.status-unknown,.status-unavailable,.status-disconnected{color:var(--vscode-descriptionForeground)}.agent-alt{grid-column:1/-1;color:var(--vscode-descriptionForeground);font-size:.88em}.more{width:100%;margin-top:5px;background:none;color:var(--accent)}.page-head{margin:5px 0 12px}.page-head>div:last-child{display:flex;gap:6px}.primary{color:var(--vscode-button-foreground);background:var(--vscode-button-background)}.filters{display:grid;grid-template-columns:minmax(180px,1fr) repeat(3,minmax(130px,auto));gap:6px;margin-bottom:8px}.filters input,.filters select{min-width:0;padding:6px 8px;border:1px solid var(--vscode-input-border,var(--vscode-panel-border));border-radius:5px;color:var(--vscode-input-foreground);background:var(--vscode-input-background)}.table-wrap{overflow:auto;border:1px solid var(--vscode-panel-border);border-radius:7px}table{width:100%;border-collapse:collapse}th,td{padding:7px 9px;border-bottom:1px solid var(--vscode-panel-border);text-align:left;vertical-align:top}th{position:sticky;top:0;background:var(--vscode-editorWidget-background);color:var(--vscode-descriptionForeground)}td small{display:block;color:var(--vscode-descriptionForeground)}.provider,.tags span{display:inline-block;padding:1px 6px;border-radius:999px;background:color-mix(in srgb,var(--accent) 15%,transparent);font-size:.82em}.tags{display:flex;flex-wrap:wrap;gap:3px}.agent-list,.account-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:7px}.agent-list .agent-item,.account-grid .account-item{padding:9px 10px;border:1px solid var(--vscode-panel-border);border-radius:7px;background:var(--vscode-editorWidget-background)}.notice{margin:8px 16px;padding:7px 10px;border-radius:5px}.notice.error{border-left:3px solid var(--danger);background:color-mix(in srgb,var(--danger) 12%,transparent)}.view[hidden],[data-model][hidden]{display:none}@media(max-width:1050px){.dashboard{grid-template-columns:minmax(340px,1.5fr) minmax(240px,1fr)}.accounts-card{grid-column:2}.filters{grid-template-columns:1fr 1fr}}@media(max-width:700px){.topbar{gap:12px;overflow-x:auto}.topbar nav{gap:12px}.dashboard{grid-template-columns:1fr}.accounts-card{grid-column:auto}.insight{display:block}.insight strong{display:block;margin-bottom:2px}.filters{grid-template-columns:1fr}.rank-columns{grid-template-columns:1fr}.metrics{gap:6px 16px}.table-wrap{border-left:0;border-right:0}.agent-list,.account-grid{grid-template-columns:1fr}}`
